mapper.update:
UPDATE historical_group_pull_execution
SET operation_account_id = #{operationAccountId},
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND pull_status = #{pendingStatus}

UPDATE historical_group_pull_execution
SET pull_status = #{targetStatus},
    started_at = COALESCE(started_at, #{startedAt}),
    updated_at = #{startedAt}
WHERE id = #{id}
  AND pull_status = #{expectedStatus}

UPDATE historical_group_pull_execution
SET marketing_status = #{sendingStatus},
    marketing_template_id = #{marketingTemplateId},
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND marketing_status = #{notStartedStatus}

UPDATE historical_group_pull_execution
SET marketing_status = #{row.marketingStatus},
    send_success_count = #{row.sendSuccessCount},
    send_failure_count = #{row.sendFailureCount},
    updated_at = #{row.updatedAt}
WHERE id = #{row.id}
  AND marketing_status = #{sendingStatus}

UPDATE historical_group_pull_execution
SET puller_account_id = #{pullerAccountId},
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND pull_status = #{runningStatus}
  AND puller_account_id IS NULL

UPDATE historical_group_pull_execution e
SET e.pull_success_count = (
      SELECT COUNT(*) FROM historical_group_pull_member m
      WHERE m.tenant_id = e.tenant_id AND m.execution_id = e.id
        AND m.add_status = #{addSuccessStatus}
    ),
    e.pull_failure_count = (
      SELECT COUNT(*) FROM historical_group_pull_member m
      WHERE m.tenant_id = e.tenant_id AND m.execution_id = e.id
        AND m.add_status != #{addSuccessStatus}
    ),
    e.send_success_count = (
      SELECT COUNT(*) FROM historical_group_pull_member m
      WHERE m.tenant_id = e.tenant_id AND m.execution_id = e.id
        AND m.send_status = #{sendSuccessStatus}
    ),
    e.send_failure_count = (
      SELECT COUNT(*) FROM historical_group_pull_member m
      WHERE m.tenant_id = e.tenant_id AND m.execution_id = e.id
        AND m.send_status = #{sendFailedStatus}
    ),
    e.updated_at = #{updatedAt}
WHERE e.id = #{id}

UPDATE historical_group_pull_execution
SET pull_status = CASE
      WHEN pull_status = #{runningPullStatus} THEN #{failedPullStatus}
      ELSE pull_status
    END,
    marketing_status = CASE
      WHEN marketing_status = #{sendingMarketingStatus} THEN #{failedMarketingStatus}
      ELSE marketing_status
    END,
    failure_stage = COALESCE(failure_stage, #{failureStage}),
    error_code = #{errorCode},
    error_message = #{errorMessage},
    finished_at = #{finishedAt},
    updated_at = #{finishedAt}
WHERE pull_status = #{runningPullStatus}
   OR marketing_status = #{sendingMarketingStatus}
